import{_ as i,c as e,o as r,ae as l}from"./chunks/framework.CHDT0Kbg.js";const t="/assets/home.BY0cCzCQ.BY0cCzCQ.webp",p=JSON.parse('{"title":"Avium UI，一个更适合国人体质的类原生系统","description":"","frontmatter":{"title":"Avium UI，一个更适合国人体质的类原生系统","date":"2025-12-07T22:50:18.000Z","author":"cgfgm","cover":"https://imgapi.xl0408.top/index.php","excerpt":"AviumUI 是一个基于 LineageOS 的定制系统项目，专注于用户需求、美观界面和功能强化。其特色功能包括无感支付、上下文建议、状态栏歌词、音乐锁屏等，旨在提供无缝融入日常使用习惯的系统体验。","categories":["ROM Reviews"],"tags":["AviumUI","Custom ROM","Android"]},"headers":[],"relativePath":"Blog/avium-ui-review.md","filePath":"Blog/avium-ui-review.md"}'),o={name:"Blog/avium-ui-review.md"};function h(n,a,u,s,d,m){return r(),e("div",null,[...a[0]||(a[0]=[l('<p><img src="'+t+'" alt="AviumUI 主界面"></p><h2 id="什么是-aviumui" tabindex="-1">什么是 AviumUI？ <a class="header-anchor" href="#什么是-aviumui" aria-label="Permalink to &quot;什么是 AviumUI？&quot;">​</a></h2><p>✨ <strong>AviumUI 是一个由国内发起、基于 LineageOS 的定制系统项目</strong></p><p>我们专注于用户所需、美观界面、原汁原味、强化功能等理念的发展。不断吸取来自各种 ROM 的优秀功能，同时创造独一无二的新奇体验。每一项功能的增加都经过深思熟虑，在开发难度与体验之间寻找最佳平衡。</p><p>我们的目标是：<strong>提供真正需要、无缝融入日常使用习惯的系统体验。</strong> 😉</p><p>👉 <a href="https://aviumui.org" target="_blank" rel="noreferrer">AviumUI 官方网站</a></p><h2 id="🌟-核心功能特性" tabindex="-1">🌟 核心功能特性 <a class="header-anchor" href="#🌟-核心功能特性" aria-label="Permalink to &quot;🌟 核心功能特性&quot;">​</a></h2><h3 id="🪙-nfc-无感支付" tabindex="-1">🪙 NFC 无感支付 <a class="header-anchor" href="#🪙-nfc-无感支付" aria-label="Permalink to &quot;🪙 NFC 无感支付&quot;">​</a></h3><p>通过识别 NFC 标签快速跳转到目标应用，目前已支持 <strong>支付宝、银联</strong>，让支付更加便捷高效。</p><h3 id="🌙-moon-suggestion-上下文建议" tabindex="-1">🌙 Moon Suggestion 上下文建议 <a class="header-anchor" href="#🌙-moon-suggestion-上下文建议" aria-label="Permalink to &quot;🌙 Moon Suggestion 上下文建议&quot;">​</a></h3><p>智能识别使用场景，提供贴心建议：</p><ul><li>在屏幕半暗时点击屏幕 → 建议 <strong>屏幕常亮</strong></li><li>开启手电筒时 → 建议 <strong>快速关闭</strong></li><li>连接到耳机时 → 推荐打开常用音乐 App</li><li>复制 App 链接时 → 推荐快速打开 App</li><li>复制快递单号 → 推荐快速查询</li><li>基于上下文使用浮动图标提供快捷操作</li></ul><h3 id="🪄-avium-绝招功能" tabindex="-1">🪄 Avium 绝招功能 <a class="header-anchor" href="#🪄-avium-绝招功能" aria-label="Permalink to &quot;🪄 Avium 绝招功能&quot;">​</a></h3><h4 id="状态栏歌词" tabindex="-1">状态栏歌词 <a class="header-anchor" href="#状态栏歌词" aria-label="Permalink to &quot;状态栏歌词&quot;">​</a></h4><p>实时显示正在播放的音乐歌词，让你在使用手机时也能轻松查看歌词。</p><h4 id="音乐锁屏" tabindex="-1">音乐锁屏 <a class="header-anchor" href="#音乐锁屏" aria-label="Permalink to &quot;音乐锁屏&quot;">​</a></h4><p>播放音乐时显示 <strong>黑胶唱片效果</strong>，增强音乐沉浸感，让锁屏不再单调。</p><h4 id="ui-深度扩展" tabindex="-1">UI 深度扩展 <a class="header-anchor" href="#ui-深度扩展" aria-label="Permalink to &quot;UI 深度扩展&quot;">​</a></h4><ul><li>禁用锁屏压暗功能</li><li>启用桌面 <strong>全层级模糊效果</strong></li><li>应用开闭时模糊底部图层</li><li>启动应用时允许 <strong>暂时禁用所有传感器 6 秒</strong></li><li>长按屏幕导航条 → 启用 <strong>屏幕 OCR</strong> 功能</li><li>允许用户遍历当前视图树以提取资源文件</li><li><strong>强制截图</strong> 功能，突破应用限制</li></ul><h3 id="🕒-万象时钟-全新锁屏系统" tabindex="-1">🕒 万象时钟（全新锁屏系统） <a class="header-anchor" href="#🕒-万象时钟-全新锁屏系统" aria-label="Permalink to &quot;🕒 万象时钟（全新锁屏系统）&quot;">​</a></h3><ul><li>引入全新的锁屏框架</li><li>新增 <strong>16 种全新锁屏样式</strong></li><li>支持 <strong>高阶材质效果</strong>（Material You / Blur / 动态）</li><li>个性化定制程度高，满足不同用户需求</li></ul><h3 id="🖼-景深壁纸" tabindex="-1">🖼 景深壁纸 <a class="header-anchor" href="#🖼-景深壁纸" aria-label="Permalink to &quot;🖼 景深壁纸&quot;">​</a></h3><ul><li>带来更加沉浸的壁纸体验</li><li>景深随视图变化产生动态效果</li><li>让你的桌面更具层次感和立体感</li></ul><h3 id="📡-设备互传-catshare" tabindex="-1">📡 设备互传 - CatShare <a class="header-anchor" href="#📡-设备互传-catshare" aria-label="Permalink to &quot;📡 设备互传 - CatShare&quot;">​</a></h3><ul><li>引入全新的文件选择界面</li><li>深度融合系统，操作流畅</li><li>与兼容「互传联盟」的设备直接共享文件</li><li>高速传输，无需网络</li></ul><h3 id="🧩-多任务协同" tabindex="-1">🧩 多任务协同 <a class="header-anchor" href="#🧩-多任务协同" aria-label="Permalink to &quot;🧩 多任务协同&quot;">​</a></h3><h4 id="气泡小窗-增强版" tabindex="-1">气泡小窗（增强版） <a class="header-anchor" href="#气泡小窗-增强版" aria-label="Permalink to &quot;气泡小窗（增强版）&quot;">​</a></h4><p>在原有气泡通知基础上支持直接启动应用，提升多任务处理效率。</p><h4 id="轻量小窗" tabindex="-1">轻量小窗 <a class="header-anchor" href="#轻量小窗" aria-label="Permalink to &quot;轻量小窗&quot;">​</a></h4><ul><li>通过手势快速唤醒</li><li>即用即走，轻量便捷</li><li>不占用过多系统资源</li></ul><h4 id="手势唤醒" tabindex="-1">手势唤醒 <a class="header-anchor" href="#手势唤醒" aria-label="Permalink to &quot;手势唤醒&quot;">​</a></h4><p>从屏幕底部两侧向中心滑动即可唤醒菜单，操作更加快捷。</p><h3 id="⚡-闪光速记" tabindex="-1">⚡ 闪光速记 <a class="header-anchor" href="#⚡-闪光速记" aria-label="Permalink to &quot;⚡ 闪光速记&quot;">​</a></h3><ul><li>快速记录复制内容并可立即编辑</li><li>让灵感不丢失、效率更顺手</li><li>支持多种格式的内容记录</li></ul><h3 id="🧭-系统-ui-ux-优化" tabindex="-1">🧭 系统 UI / UX 优化 <a class="header-anchor" href="#🧭-系统-ui-ux-优化" aria-label="Permalink to &quot;🧭 系统 UI / UX 优化&quot;">​</a></h3><h4 id="轻盈图标" tabindex="-1">轻盈图标 <a class="header-anchor" href="#轻盈图标" aria-label="Permalink to &quot;轻盈图标&quot;">​</a></h4><p>更加清新、现代的图标设计，提升整体视觉体验。</p><h2 id="📱-支持机型" tabindex="-1">📱 支持机型 <a class="header-anchor" href="#📱-支持机型" aria-label="Permalink to &quot;📱 支持机型&quot;">​</a></h2><p>AviumUI 支持多种机型，包括红米、小米等系列设备。具体支持机型可前往 <a href="https://aviumui.org" target="_blank" rel="noreferrer">官方网站</a> 查看。</p><h2 id="📥-下载与安装" tabindex="-1">📥 下载与安装 <a class="header-anchor" href="#📥-下载与安装" aria-label="Permalink to &quot;📥 下载与安装&quot;">​</a></h2><ol><li>前往 <a href="https://aviumui.org" target="_blank" rel="noreferrer">AviumUI 官方网站</a> 下载对应机型的固件包</li><li>确保设备已解锁 Bootloader</li><li>使用 Recovery 刷入固件包</li><li>首次启动可能需要较长时间，请耐心等待</li></ol><h2 id="💬-社区与支持" tabindex="-1">💬 社区与支持 <a class="header-anchor" href="#💬-社区与支持" aria-label="Permalink to &quot;💬 社区与支持&quot;">​</a></h2><ul><li>官方网站：<a href="https://aviumui.org" target="_blank" rel="noreferrer">https://aviumui.org</a></li><li>官方论坛：<a href="https://forum.aviumui.org" target="_blank" rel="noreferrer">https://forum.aviumui.org</a></li><li>Telegram 群组：<a href="https://t.me/aviumui" target="_blank" rel="noreferrer">https://t.me/aviumui</a></li></ul><h2 id="📝-总结" tabindex="-1">📝 总结 <a class="header-anchor" href="#📝-总结" aria-label="Permalink to &quot;📝 总结&quot;">​</a></h2><p>AviumUI 是一款非常出色的类原生定制系统，它在保持原生系统流畅度的同时，加入了许多实用的功能和精美的设计。无论是 NFC 无感支付、上下文建议，还是状态栏歌词、音乐锁屏，都能让用户的日常使用更加便捷和愉悦。</p><p>如果你厌倦了原厂系统的臃肿，又想要一个功能丰富、流畅稳定的系统，那么 AviumUI 绝对值得一试！</p>',46)])])}const g=i(o,[["render",h]]);export{p as __pageData,g as default};
